local ForgeClinkerBreakerMaker = {}
local PRODUCTS = {
    iron_forgeclinkerbreaker = { name = "Železni lomilec zlindre", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni lomilec zlindre za kovace." },
    bronze_forgeclinkerbreaker = { name = "Bronast lomilec zlindre", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast lomilec zlindre za kovace." },
    silver_forgeclinkerbreaker = { name = "Srebrn lomilec zlindre", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn lomilec zlindre za kovace." },
    gilded_forgeclinkerbreaker = { name = "Pozlačen lomilec zlindre", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen lomilec zlindre za kovace." },
    jewel_set_forgeclinkerbreaker = { name = "Draguljast lomilec zlindre", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast lomilec zlindre za kovace." },
    royal_sovereign_forgeclinkerbreaker = { name = "Kraljevski suveren lomilec zlindre", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren lomilec zlindre z biseri za krono." },
}
local BUILDINGS = {
    forgeclinkerbreaker_workshop = { name = "Forgeclinkerbreaker delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    forgeclinkerbreaker_house = { name = "Forgeclinkerbreaker hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_forgeclinkerbreaker_atelier = { name = "Mojstrski forgeclinkerbreaker atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_forgeclinkerbreaker_palace = { name = "Suverena forgeclinkerbreaker palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
ForgeClinkerBreakerMaker.ironStock=18; ForgeClinkerBreakerMaker.bronzeStock=14; ForgeClinkerBreakerMaker.woodStock=10; ForgeClinkerBreakerMaker.leatherStock=8; ForgeClinkerBreakerMaker.silverStock=8; ForgeClinkerBreakerMaker.goldStock=6; ForgeClinkerBreakerMaker.jewelStock=4; ForgeClinkerBreakerMaker.pearlStock=4
ForgeClinkerBreakerMaker.productStock = {}; ForgeClinkerBreakerMaker.buildings = {}; ForgeClinkerBreakerMaker.maker = nil; ForgeClinkerBreakerMaker.activeMaking = {}; ForgeClinkerBreakerMaker.totalProducts = 0; ForgeClinkerBreakerMaker.dayTimer = 0
function ForgeClinkerBreakerMaker.init() ForgeClinkerBreakerMaker.ironStock=18; ForgeClinkerBreakerMaker.bronzeStock=14; ForgeClinkerBreakerMaker.woodStock=10; ForgeClinkerBreakerMaker.leatherStock=8; ForgeClinkerBreakerMaker.silverStock=8; ForgeClinkerBreakerMaker.goldStock=6; ForgeClinkerBreakerMaker.jewelStock=4; ForgeClinkerBreakerMaker.pearlStock=4; ForgeClinkerBreakerMaker.productStock={}; ForgeClinkerBreakerMaker.buildings={}; ForgeClinkerBreakerMaker.maker=nil; ForgeClinkerBreakerMaker.activeMaking={}; ForgeClinkerBreakerMaker.totalProducts=0; ForgeClinkerBreakerMaker.dayTimer=0; print("[ForgeClinkerBreakerMaker] Royal Forge Clinker Breaker Maker System initialized (6 products, 4 buildings)") end
function ForgeClinkerBreakerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ForgeClinkerBreakerMaker.maker={name=n or ("Lomilnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lomilnik najet: %s (spretnost: %d)",ForgeClinkerBreakerMaker.maker.name,s),"success") end; return true end
function ForgeClinkerBreakerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ForgeClinkerBreakerMaker.build(id) local ok,e=ForgeClinkerBreakerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ForgeClinkerBreakerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ForgeClinkerBreakerMaker.getQualityBonus() local b=0; for _,bd in ipairs(ForgeClinkerBreakerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ForgeClinkerBreakerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ForgeClinkerBreakerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ForgeClinkerBreakerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ForgeClinkerBreakerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ForgeClinkerBreakerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ForgeClinkerBreakerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ForgeClinkerBreakerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ForgeClinkerBreakerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ForgeClinkerBreakerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ForgeClinkerBreakerMaker.buildings==0 then return false,"Potrebna lomilna delavnica" end; if not ForgeClinkerBreakerMaker.maker then return false,"Potreben lomilnik" end; return true end
function ForgeClinkerBreakerMaker.make(pt,qty) qty=qty or 1; local ok,e=ForgeClinkerBreakerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ForgeClinkerBreakerMaker.ironStock=ForgeClinkerBreakerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ForgeClinkerBreakerMaker.bronzeStock=ForgeClinkerBreakerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ForgeClinkerBreakerMaker.woodStock=ForgeClinkerBreakerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ForgeClinkerBreakerMaker.leatherStock=ForgeClinkerBreakerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ForgeClinkerBreakerMaker.silverStock=ForgeClinkerBreakerMaker.silverStock-d.silverCost*qty end; if d.goldCost then ForgeClinkerBreakerMaker.goldStock=ForgeClinkerBreakerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ForgeClinkerBreakerMaker.jewelStock=ForgeClinkerBreakerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ForgeClinkerBreakerMaker.pearlStock=ForgeClinkerBreakerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ForgeClinkerBreakerMaker.maker then t=math.max(1,t-math.floor(ForgeClinkerBreakerMaker.maker.skill/13)) end; table.insert(ForgeClinkerBreakerMaker.activeMaking,{id="forgeclinkerbreaker_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ForgeClinkerBreakerMaker.completeMaking(m) local q=1.0+(ForgeClinkerBreakerMaker.getQualityBonus()/100); if ForgeClinkerBreakerMaker.maker then q=q+(ForgeClinkerBreakerMaker.maker.skill/140) end; q=math.min(2.5,q); ForgeClinkerBreakerMaker.productStock[m.productType]=(ForgeClinkerBreakerMaker.productStock[m.productType] or 0)+m.quantity; ForgeClinkerBreakerMaker.totalProducts=ForgeClinkerBreakerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ForgeClinkerBreakerMaker.maker then ForgeClinkerBreakerMaker.maker.itemsMade=ForgeClinkerBreakerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ForgeClinkerBreakerMaker.maker.skill=math.min(100,ForgeClinkerBreakerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lomilec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"forgeclinkerbreaker.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ForgeClinkerBreakerMaker.update(dt) if not _G.state then return end; ForgeClinkerBreakerMaker.dayTimer=ForgeClinkerBreakerMaker.dayTimer+dt; if ForgeClinkerBreakerMaker.dayTimer>=30 then ForgeClinkerBreakerMaker.dayTimer=0; for i=#ForgeClinkerBreakerMaker.activeMaking,1,-1 do local m=ForgeClinkerBreakerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ForgeClinkerBreakerMaker.completeMaking(m); table.remove(ForgeClinkerBreakerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ForgeClinkerBreakerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ForgeClinkerBreakerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ForgeClinkerBreakerMaker.getStats() return {ironStock=ForgeClinkerBreakerMaker.ironStock,bronzeStock=ForgeClinkerBreakerMaker.bronzeStock,woodStock=ForgeClinkerBreakerMaker.woodStock,leatherStock=ForgeClinkerBreakerMaker.leatherStock,silverStock=ForgeClinkerBreakerMaker.silverStock,goldStock=ForgeClinkerBreakerMaker.goldStock,jewelStock=ForgeClinkerBreakerMaker.jewelStock,pearlStock=ForgeClinkerBreakerMaker.pearlStock,productStock=ForgeClinkerBreakerMaker.productStock,numBuildings=#ForgeClinkerBreakerMaker.buildings,hasMaker=ForgeClinkerBreakerMaker.maker~=nil,makerName=ForgeClinkerBreakerMaker.maker and ForgeClinkerBreakerMaker.maker.name or "—",makerSkill=ForgeClinkerBreakerMaker.maker and ForgeClinkerBreakerMaker.maker.skill or 0,activeMaking=#ForgeClinkerBreakerMaker.activeMaking,totalProducts=ForgeClinkerBreakerMaker.totalProducts} end
return ForgeClinkerBreakerMaker
